const categories=['ramadan','startfit'];
const hidden=(h,k,v)=>`<input type="hidden" name="${k}" value="${h(v)}">`;
const day=()=>new Date().toISOString().slice(0,10);
const select=(h,name,options,value)=>`<select name="${name}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select>`;
const action=(t,h,btn,r,op,label,extra='')=>btn(t(label),'programAction',`data-module="campaigns" data-id="${h(r.id)}" data-op="${op}" ${extra}`,'secondary');
function edit(t,h,r,category){
  return `<form class="stack" data-form="programs">${hidden(h,'module','campaigns')}${hidden(h,'operation',r?'update':'create')}${hidden(h,'scope','public')}${r?hidden(h,'id',r.id):''}${category!=='campaigns'?hidden(h,'category',category):`<label>${t('programCategory')}${select(h,'category',categories.map(c=>[c,t(c)]),r?.category||'ramadan')}</label>`}<label>${t('programTitle')}<input required name="title" maxlength="100" value="${h(r?.title||'')}"></label><label>${t('programDescription')}<textarea required name="description" maxlength="2000">${h(r?.description||'')}</textarea></label><label>${t('language')}${select(h,'language',['ar','en','sv'].map(l=>[l,t('lang_'+l)]),r?.language||'en')}</label><div class="grid"><label>${t('clubStart')}<input required type="date" name="start" value="${h(r?.start||day())}"></label><label>${t('clubEnd')}<input required type="date" name="end" value="${h(r?.end||day())}"></label></div><label>${t('programCapacity')}<input type="number" name="campaignCapacity" min="1" max="1000" value="${h(r?.capacity??'')}"></label><small>${t('campaignCapacityHint')}</small><label>${t('campaignTasks')}<textarea name="campaignTasks" maxlength="1212" rows="4">${h((r?.tasks||[]).map(x=>x.title).join('\n'))}</textarea></label><small>${t('campaignTaskHint')}</small><button class="primary" type="submit">${t(r?'save':'create')}</button></form>`;
}
function card(t,h,btn,r,admin){
  const status=r.campaignStatus||r.status,progress=Math.min(100,Math.max(0,Number(r.progress)||0));
  return `<details class="card stack" open><summary><span class="row wrap space"><b>${h(r.title)}</b><span class="badge ${status==='active'?'green':'gold'}">${t('campaignStatus_'+status)}</span></span></summary><p class="post-text">${h(r.description)}</p><small>${h(r.language.toUpperCase())} · ${t(r.category)} · ${h(r.start)} — ${h(r.end)}</small><div class="row wrap"><span class="badge">${r.count}${r.capacity?'/'+r.capacity:''} ${t('programParticipants')}</span><span class="badge">${r.duration} ${t('campaignDays')}</span><span class="badge ${r.signupAvailable?'green':'gold'}">${t(r.signupAvailable?'campaignSignupOpen':'campaignSignupClosed')}</span></div>${!admin&&r.status==='published'&&(r.joined||r.signupAvailable)?action(t,h,btn,r,r.joined?'leave':'join',r.joined?'leave':'join'):''}${!admin&&r.joined?`<section class="stack rule"><h3>${t('campaignMyProgress')}</h3><div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div><small>${progress}% · ${r.checkins.length} ${t('campaignCheckins')}</small>${status==='active'?`${r.checkedInToday?`<span class="badge green">${t('campaignCheckedIn')}</span>`:action(t,h,btn,r,'checkin','checkin')}<h3>${t('campaignTasks')}</h3>${r.tasks.map(task=>{const done=r.taskChecksToday.includes(task.id);return `<div class="row rule wrap"><span class="grow">${h(task.title)}</span>${action(t,h,btn,r,'campaignTaskToggle',done?'campaignUndo':'done',`data-task="${h(task.id)}" data-completed="${!done}" aria-pressed="${done}"`)}</div>`}).join('')||`<small>${t('noItems')}</small>`}`:''}</section>`:''}${r.manage?`<section class="rule stack"><div class="row wrap">${action(t,h,btn,r,r.status==='published'?'draft':'publish',r.status==='published'?'programUnpublish':'programPublish')}${action(t,h,btn,r,'archive','programArchive')}${action(t,h,btn,r,'campaignSignup',r.enrollmentOpen?'campaignCloseSignup':'campaignOpenSignup',`data-enabled="${!r.enrollmentOpen}"`)}</div><details><summary>${t('wellnessEdit')}</summary>${edit(t,h,r,r.category)}</details><details><summary>${t('campaignRoster')} · ${r.count}</summary><div class="row wrap"><span>${(r.roster||[]).reduce((sum,e)=>sum+e.checkins,0)} ${t('campaignCheckins')}</span></div>${(r.roster||[]).map(e=>`<div class="row rule space"><span>${h(e.name)}</span><span>${e.checkins} ${t('campaignCheckins')}</span></div>`).join('')||`<small>${t('noItems')}</small>`}</details></section>`:''}</details>`;
}
export function campaignPage({state,id,t,h,btn,filter={}}){
  const p=state.programs,rows=p.items.filter(r=>r.module==='campaigns'&&(id==='campaigns'||r.category===id)&&(!filter.language||r.language===filter.language)&&(!filter.query||[r.title,r.description].some(v=>v.toLowerCase().includes(filter.query.toLowerCase()))));
  return `<div class="stack"><section class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / CAMPAIGNS</span><h1>${t(id)}</h1><p>${t('campaignIntro')}</p></section><section class="card stack"><div class="row wrap">${['campaigns',...categories].map(c=>btn(t(c),'nav',`data-id="${c}" aria-pressed="${c===id}"`,'chip '+(c===id?'active':''))).join('')}</div><p class="notice">${t('programLocalNotice')}</p><form class="row wrap" data-form="programFilter">${hidden(h,'module',id)}<label>${t('programSearch')}<input type="search" name="query" maxlength="100" value="${h(filter.query||'')}"></label><label>${t('language')}${select(h,'language',[['',t('all')],...['ar','en','sv'].map(l=>[l,t('lang_'+l)])],filter.language||'')}</label><button class="secondary" type="submit">${t('programSearch')}</button></form>${p.canAdmin?`<details><summary>${t('campaignCreate')}</summary>${edit(t,h,null,id)}</details>`:''}</section>${rows.map(r=>card(t,h,btn,r,p.canAdmin)).join('')||`<section class="card empty">${t('campaignEmpty')}</section>`}</div>`;
}
